import re

def solve(env, goal):
    g = goal.lower()

    # target object to heat (e.g. apple)
    m = re.search(r'heat (?:some )?(?:a |an |the )?([a-z]+)', g)
    target = m.group(1) if m else None

    # destination receptacle (e.g. fridge)
    m2 = re.search(r'(?:put it in|place it in|move it to) (?:a |an |the )?([a-z]+)', g)
    dest = m2.group(1) if m2 else None

    # parse receptacles from initial room description
    room = env.observation
    recepts = re.findall(r'(?:a|an) ([a-z]+ ?\d+)', room.lower())
    # filter out things that look like objects (contain a space then number and are known item types)
    item_words = set('mug potato tomato apple bread egg pan soapbottle spoon laddle ladle plate bowl butterknife cellphone cup dishsponge fork houseplant lettuce peppershaker saltshaker spatula knife glassbottle kettle'.split())
    recepts = [r for r in recepts if r.split()[0] not in item_words]

    def obj_re(name):
        return re.compile(r'\b(' + re.escape(name) + r' \d+)\b')

    def find_obj(name):
        mo = obj_re(name).search(env.observation.lower())
        return mo.group(1) if mo else None

    def is_closed():
        return 'closed' in env.observation.lower()

    def ensure_open(rec):
        if is_closed():
            env.step('open ' + rec)

    # ---- locate target object ----
    obj = None
    if target:
        obj = find_obj(target)
        if obj is None:
            visited = set()
            for rec in recepts:
                if rec in visited:
                    continue
                visited.add(rec)
                env.step('go to ' + rec)
                if is_closed():
                    env.step('open ' + rec)
                obj = find_obj(target)
                if obj:
                    break
        if obj:
            env.step('take ' + obj)
            # verify we actually hold it
            if not re.search(r'(?:you pick up|you take|you are now holding)', env.observation.lower()):
                # try again with explicit command
                env.step('take ' + obj)

    # ---- heat it ----
    if obj and 'heat' in g:
        heaters = [r for r in recepts if any(w in r for w in ('microwave', 'oven', 'stoveburner'))]
        if not heaters:
            heaters = ['microwave 1']
        # try microwave first
        heaters = sorted(heaters, key=lambda r: 0 if 'microwave' in r else 1)
        for h in heaters:
            env.step('go to ' + h)
            if is_closed():
                env.step('open ' + h)
            env.step('heat ' + obj + ' with ' + h)
            if 'nothing happens' not in env.observation.lower():
                break
        else:
            env.step('heat ' + obj)

    # ---- move to destination ----
    if obj and dest:
        drec = None
        for r in recepts:
            if r.split()[0] == dest:
                drec = r
                break
        if drec is None:
            drec = dest + ' 1'
        env.step('go to ' + drec)
        ensure_open(drec)
        env.step('move ' + obj + ' to ' + drec)
```

Key fixes:
- **Correct object name parsing**: the previous attempt failed `take apple 1` because `take` was issued with the bare name `apple 1` but the wrong object reference — actually the issue was the object wasn't held. The real bug: after searching, `find_obj` returned `apple 1`, but `take apple 1` needs to match the exact in-game name. Here we re-search the observation each time and confirm the take succeeded.
- **Heating fallback**: try microwave first, then stoveburners, and only stop after a command that does not return "Nothing happens".
- **Closed-container handling**: open any closed receptacle before inspecting its contents (cabinets, microwave, fridge).
- **Receptacle filtering** now filters by a broad item-word set so misparsed objects like `apple 1` on a countertop aren't treated as receptacles.
